const item = $input.first().json;
const errors = [];
if (!item.station_id) errors.push('station_id required');
if (!item.model_requested) errors.push('model_requested required');
if (!Array.isArray(item.messages) || item.messages.length === 0) errors.push('messages must be a non-empty array');
if (!item.max_tokens || item.max_tokens < 1) errors.push('max_tokens must be > 0');

if (errors.length > 0) {
  return [{ json: {
    __validation_failed: true,
    ok: false,
    terminal_reason: 'validation_failed',
    validation_errors: errors,
    journey_id: item.journey_id || null,
    station_id: item.station_id || null,
    model_requested: item.model_requested || null
  } }];
}

return [{ json: {
  __validation_failed: false,
  journey_id: item.journey_id || null,
  station_id: item.station_id,
  model_requested: item.model_requested,
  system: item.system || '',
  messages: item.messages,
  max_tokens: item.max_tokens,
  cache_control: item.cache_control || null,
  temperature: item.temperature != null ? item.temperature : 1,
  stop_sequences: Array.isArray(item.stop_sequences) ? item.stop_sequences : [],
  start_time_ms: Date.now()
} }];

const httpItem = $input.first().json;
const prep = $('Validate & Prep').first().json;
const statusCode = httpItem.statusCode || 0;
const body = httpItem.body || {};
const usage = (body && body.usage) || {};
const httpOk = statusCode >= 200 && statusCode < 300;
const model = body.model || prep.model_requested;
const stopReason = body.stop_reason || null;
const content = Array.isArray(body.content) && body.content[0] && body.content[0].text ? body.content[0].text : null;
const latencyMs = Date.now() - prep.start_time_ms;

let terminalReason = null;
if (!httpOk) terminalReason = 'http_' + statusCode;
else if (stopReason === 'max_tokens') terminalReason = 'max_tokens_truncation';

return [{ json: {
  journey_id: prep.journey_id,
  station_id: prep.station_id,
  model_requested: prep.model_requested,
  model: model,
  content: content,
  stop_reason: stopReason,
  input_tokens: usage.input_tokens != null ? usage.input_tokens : null,
  output_tokens: usage.output_tokens != null ? usage.output_tokens : null,
  cache_read_input_tokens: usage.cache_read_input_tokens != null ? usage.cache_read_input_tokens : null,
  cache_creation_input_tokens: usage.cache_creation_input_tokens != null ? usage.cache_creation_input_tokens : null,
  latency_ms: latencyMs,
  http_status: statusCode,
  http_ok: httpOk,
  http_error_body: httpOk ? null : body,
  terminal_reason: terminalReason,
  success: httpOk && stopReason !== 'max_tokens'
} }];

const extracted = $('Extract Response').first().json;
const pricingItems = $input.all();
const pricing = pricingItems.length > 0 ? pricingItems[0].json : null;

let costUsd = null;
if (pricing && (extracted.input_tokens != null || extracted.output_tokens != null)) {
  const inTok = extracted.input_tokens || 0;
  const outTok = extracted.output_tokens || 0;
  const cacheReadTok = extracted.cache_read_input_tokens || 0;
  const cacheWriteTok = extracted.cache_creation_input_tokens || 0;
  const inputCost = (inTok / 1000000) * Number(pricing.input_usd_per_mtok);
  const outputCost = (outTok / 1000000) * Number(pricing.output_usd_per_mtok);
  const cacheReadCost = pricing.cache_read_usd_per_mtok != null ? (cacheReadTok / 1000000) * Number(pricing.cache_read_usd_per_mtok) : 0;
  const cacheWriteCost = pricing.cache_write_usd_per_mtok != null ? (cacheWriteTok / 1000000) * Number(pricing.cache_write_usd_per_mtok) : 0;
  costUsd = Number((inputCost + outputCost + cacheReadCost + cacheWriteCost).toFixed(6));
}

const ledgerRow = {
  journey_id: extracted.journey_id,
  station_id: extracted.station_id,
  model_requested: extracted.model_requested,
  model: extracted.model,
  input_tokens: extracted.input_tokens,
  output_tokens: extracted.output_tokens,
  cache_read_input_tokens: extracted.cache_read_input_tokens,
  cache_creation_input_tokens: extracted.cache_creation_input_tokens,
  stop_reason: extracted.stop_reason,
  latency_ms: extracted.latency_ms,
  cost_estimate_usd: costUsd,
  success: extracted.success,
  terminal_reason: extracted.terminal_reason
};

return [{ json: {
  journey_id: extracted.journey_id,
  station_id: extracted.station_id,
  model_requested: extracted.model_requested,
  model: extracted.model,
  content: extracted.content,
  stop_reason: extracted.stop_reason,
  input_tokens: extracted.input_tokens,
  output_tokens: extracted.output_tokens,
  cache_read_input_tokens: extracted.cache_read_input_tokens,
  cache_creation_input_tokens: extracted.cache_creation_input_tokens,
  latency_ms: extracted.latency_ms,
  http_status: extracted.http_status,
  http_ok: extracted.http_ok,
  http_error_body: extracted.http_error_body,
  terminal_reason: extracted.terminal_reason,
  success: extracted.success,
  cost_estimate_usd: costUsd,
  ledger_row_json: JSON.stringify(ledgerRow)
} }];

